INSERT INTO stage02_choose_rank_native(test_name,ok)
SELECT label||':direct',
 CASE WHEN n<=pastafari_sql_tamil.save_modulus()
      THEN short_value=expected ELSE wide_value=expected END FROM computed
UNION ALL SELECT label||':dispatch',dispatch_value=expected FROM computed;

INSERT INTO stage02_choose_rank_native(test_name,ok)
SELECT 'invalid:short-zero',pastafari_sql_tamil.choose_rank_short(
 ROW(1::numeric,1)::pastafari_sql_tamil.answer_stream,0) IS NULL
UNION ALL SELECT 'invalid:short-fractional',pastafari_sql_tamil.choose_rank_short(
 ROW(1::numeric,1)::pastafari_sql_tamil.answer_stream,2.5) IS NULL
UNION ALL SELECT 'invalid:short-over-M',pastafari_sql_tamil.choose_rank_short(
 ROW(1::numeric,1)::pastafari_sql_tamil.answer_stream,
 pastafari_sql_tamil.save_modulus()+1) IS NULL
UNION ALL SELECT 'invalid:wide-at-M',pastafari_sql_tamil.choose_rank_wide(
 ROW(1::numeric,1)::pastafari_sql_tamil.answer_stream,
 pastafari_sql_tamil.save_modulus()) IS NULL
UNION ALL SELECT 'invalid:wide-fractional',pastafari_sql_tamil.choose_rank_wide(
