 pastafari_sql_tamil.save_modulus()+1) IS NULL;

INSERT INTO stage02_choose_rank_native(test_name,ok)
SELECT 'metadata:reference-free',(
 SELECT count(*)=0 FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace
 WHERE n.nspname='pastafari_sql_tamil'
 AND p.proname IN ('choose_rank_short','choose_rank_wide','choose_rank')
 AND position('pastafari_sql_tamil_test' IN pg_get_functiondef(p.oid))>0)
UNION ALL SELECT 'metadata:sql',(
 SELECT count(*)=3 FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace
 JOIN pg_language l ON l.oid=p.prolang
 WHERE n.nspname='pastafari_sql_tamil' AND p.proname IN
 ('choose_rank_short','choose_rank_wide','choose_rank') AND l.lanname='sql')
UNION ALL SELECT 'metadata:immutable',(
 SELECT count(*)=3 FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace
 WHERE n.nspname='pastafari_sql_tamil' AND p.provolatile='i'
 AND p.proname IN ('choose_rank_short','choose_rank_wide','choose_rank'));

SELECT count(*) AS native_assertions FROM stage02_choose_rank_native;
COMMIT;
